const NS = 'http://www.w3.org/2000/svg';
export const hasIcon = (name) => Object.prototype.hasOwnProperty.call(P, name);

/** An inline SVG icon, 1em square in the current text colour; null for an unknown name. */
export function icon(name, cls = '') {
  if (!hasIcon(name)) return null;
  const svg = document.createElementNS(NS, 'svg');
  svg.setAttribute('viewBox', '0 0 256 256');
  svg.setAttribute('class', cls ? 'ico ' + cls : 'ico');
  svg.setAttribute('aria-hidden', 'true');
  const path = document.createElementNS(NS, 'path');
  path.setAttribute('d', P[name]);
  svg.append(path);
  return svg;
}
/** The same icon as markup, for HTML templates. */
export const iconHtml = (name, cls = '') =>
  (hasIcon(name) ? `<svg class="ico${cls ? ' ' + cls : ''}" viewBox="0 0 256 256" aria-hidden="true"><path d="${P[name]}"/></svg>` : '');

