/** Text from the settings (an icon name, or an emoji with a known icon) as an icon; anything else stays text. */
export function glyph(text, cls = '') {
  const s = String(text ?? '').trim();
  if (!s) return '';
  const name = hasIcon(s) ? s : EMOJI[s.replace(/[\uFE0E\uFE0F]/g, '')];
  return (name && icon(name, cls)) || s;
}
